      ctx.save(); ctx.beginPath(); ctx.moveTo(tx - lipR * 1.1, lipY); ctx.lineTo(tx - lipR * 1.1, by - br - 3); ctx.lineTo(tx + lipR * 1.1, by - br - 3); ctx.lineTo(tx + lipR * 1.1, lipY);
