      const sh = g.createLinearGradient(0, h * 0.15, 0, base);
      sh.addColorStop(0, 'rgba(255,253,245,1)'); sh.addColorStop(0.6, 'rgba(240,246,252,1)'); sh.addColorStop(1, 'rgba(190,208,228,1)');
      g.fillStyle = sh; g.fillRect(0, 0, w, h);
