        const bx0 = x + s * 3.2, bw = W * 0.20, bh = H * 0.040;
        ctx.strokeStyle = 'rgba(60,60,70,0.7)'; ctx.lineWidth = 0.6; ctx.beginPath(); ctx.moveTo(x + s * 1.2, y); ctx.lineTo(bx0, y); ctx.stroke();
