      ctx.fillStyle = '#ffffff'; ctx.beginPath(); ctx.moveTo(x, y - s * 1.6); ctx.lineTo(x, y - s * 0.2); ctx.lineTo(x + s * 0.8, y - s * 0.2); ctx.closePath(); ctx.fill();
