      const body = () => { ctx.beginPath(); ctx.moveTo(x0, baseY); for (let x = x0; x <= x1; x += 3) ctx.lineTo(x, crestY(d, x, W, H)); ctx.lineTo(x1, baseY); ctx.closePath(); };
