      const br = ctx.createLinearGradient(x - s * 0.25, 0, x + s * 0.25, 0);
      br.addColorStop(0, '#5a3a10'); br.addColorStop(0.45, '#b8862c'); br.addColorStop(0.75, '#ffe6a0'); br.addColorStop(1, '#c89038');
