        ctx.fillStyle = 'rgba(40,24,10,0.30)'; ctx.beginPath(); ctx.moveTo(x - 2, sb); ctx.lineTo(x + 2, sb); ctx.lineTo(x + W * 0.045, sb + H * 0.04); ctx.lineTo(x + W * 0.040, sb + H * 0.04); ctx.closePath(); ctx.fill();
