      ctx.fillStyle = '#f6e2b4'; ctx.fillRect(W * 0.335 - 1, st - 2.4, W * 0.016 + 1, 2.2); ctx.fillRect(W * 0.351 + 1, st - 2.4, W * 0.016, 2.2);
      const bx = W * 0.388, br = W * 0.0085, by = sb - br;
