        ctx.strokeStyle = 'rgba(20,50,20,0.45)'; ctx.lineWidth = 0.4; for (let k = 2; k < 38; k += 2) { const [px, py] = B(k / 40); ctx.beginPath(); ctx.moveTo(L1[k][0], L1[k][1]); ctx.lineTo(px, py); ctx.lineTo(L2[k][0], L2[k][1]); ctx.stroke(); }
