      fr.sort((p1, p2) => Math.abs(Math.cos(p2[0])) - Math.abs(Math.cos(p1[0]))).forEach(([a, L], i) => blade(a, L, i % 3 === 0 ? '#2e6e30' : i % 3 === 1 ? '#3e8a3a' : '#4e9a44', 'rgba(220,240,200,0.6)'));
