        const fs = Math.min(1, st / (dur + 0.8)); ctx.fillStyle = `rgba(255,255,255,${(0.45 * (1 - fs)).toFixed(3)})`; ctx.beginPath(); ctx.ellipse(sx, sy + 0.8, (4 + fs * 16) * big, (1 + fs * 2.4) * big, 0, 0, PI * 2); ctx.fill();
