      const mx = (bx + tipx) / 2, my = (by0 + tipy) / 2, nx = -(tipy - by0), ny = tipx - bx, nl = Math.hypot(nx, ny) || 1;
      const g = ctx.createLinearGradient(mx - w2, 0, mx + w2, 0); g.addColorStop(0, light ? '#f4fff2' : '#bfe6c4'); g.addColorStop(1, light ? '#9ad0a6' : '#5e9e70'); ctx.fillStyle = g;
      ctx.beginPath(); ctx.moveTo(bx, by0); ctx.quadraticCurveTo(mx + nx / nl * w2, my + ny / nl * w2, tipx, tipy); ctx.quadraticCurveTo(mx - nx / nl * w2, my - ny / nl * w2, bx, by0); ctx.closePath(); ctx.fill();
      ctx.strokeStyle = 'rgba(20,70,40,0.75)'; ctx.lineWidth = 0.8; ctx.stroke(); if (light && cs > 0.15) { ctx.strokeStyle = `rgba(240,192,64,${(0.85 * cs).toFixed(3)})`; ctx.lineWidth = 0.7; ctx.stroke(); }
