    ctx.fillStyle = '#12061e'; ctx.beginPath(); ctx.moveTo(-s * 0.05, -s * 0.62); ctx.quadraticCurveTo(-s * 0.55, -s * 0.55 + r1, -s * 1.05, -s * 0.30 + r2); ctx.lineTo(-s * 0.85, -s * 0.14 + r1); ctx.lineTo(-s * 1.00, -s * 0.02 + r2 * 0.6); ctx.quadraticCurveTo(-s * 0.55, s * 0.04, -s * 0.20, s * 0.02); ctx.closePath(); ctx.fill();
