    ctx.beginPath(); ctx.moveTo(-s * 0.05, s * 0.0); ctx.quadraticCurveTo(s * 0.25, s * 0.10, s * 0.28, s * 0.34); ctx.lineTo(s * 0.48, s * 0.30); ctx.lineTo(s * 0.20, s * 0.42); ctx.lineTo(s * 0.10, s * 0.20); ctx.closePath(); ctx.fill();
