  const SUN = { x: 0.30, y: 0.07 };                  // a high white noon sun over the left-hand roofs: the right side of the street in sun, the left in shade
  const STUMPS = { x: 0.615, y: 0.690 };
  // ── the camera: standing in the middle of Main Street, looking straight down it. World units are about a metre; X across, Y up, Z away from us ──
  const HZ = 0.420, CAM = 1.7, FOC = 0.3226;
