    const P = (X, Y, Z) => PJ(W, H, X, Y, Z), hz = H * HZ, SX = W * SUN.x, SY = H * SUN.y;
    const poly = (pts, fill) => { ctx.beginPath(); pts.forEach((p, i) => i ? ctx.lineTo(p[0], p[1]) : ctx.moveTo(p[0], p[1])); ctx.closePath(); if (fill) { ctx.fillStyle = fill; ctx.fill(); } };
    const seg = (a, b) => { ctx.beginPath(); ctx.moveTo(a[0], a[1]); ctx.lineTo(b[0], b[1]); ctx.stroke(); };

    // ── Sky: deep blue overhead fading to a pale haze on the horizon, the sun a white-hot disc ──
    { const g = ctx.createLinearGradient(0, 0, 0, hz); g.addColorStop(0, '#1a5cc8'); g.addColorStop(0.5, '#4a9ae4'); g.addColorStop(0.88, '#a8d4f0'); g.addColorStop(1, '#eef4ee'); ctx.fillStyle = g; ctx.fillRect(0, 0, W, hz + 4);
      const sg = ctx.createRadialGradient(SX, SY, 0, SX, SY, W * 0.28); sg.addColorStop(0, 'rgba(255,255,245,1)'); sg.addColorStop(0.07, 'rgba(255,253,230,0.7)'); sg.addColorStop(0.25, 'rgba(255,250,220,0.18)'); sg.addColorStop(1, 'rgba(255,250,220,0)'); ctx.fillStyle = sg; ctx.fillRect(0, 0, W, hz + 4);
      ctx.fillStyle = '#ffffff'; ctx.beginPath(); ctx.arc(SX, SY, H * 0.027, 0, PI * 2); ctx.fill(); }

    ctx = part === 'far' ? ctxReal : SCRATCH;
    // ── the far mountains: a blue range with snow on the high peaks, hazed by distance ──
    { const pk = [[-0.02, 0.37], [0.06, 0.30], [0.12, 0.33], [0.19, 0.265], [0.25, 0.31], [0.30, 0.285], [0.36, 0.33], [0.42, 0.30], [0.47, 0.335], [0.53, 0.29], [0.58, 0.255], [0.64, 0.305], [0.70, 0.28], [0.77, 0.325], [0.83, 0.275], [0.90, 0.31], [0.96, 0.29], [1.02, 0.34]];
      ctx.beginPath(); ctx.moveTo(-4, hz + 2); pk.forEach(([fx, fy]) => ctx.lineTo(W * fx, H * fy)); ctx.lineTo(W + 4, hz + 2); ctx.closePath(); const g = ctx.createLinearGradient(0, H * 0.25, 0, hz); g.addColorStop(0, '#8a96c4'); g.addColorStop(1, '#b8c4dc'); ctx.fillStyle = g; ctx.fill();
      ctx.save(); ctx.clip(); ctx.fillStyle = 'rgba(70,80,130,0.30)'; for (let i = 1; i < pk.length - 1; i++) { const [fx, fy] = pk[i]; ctx.beginPath(); ctx.moveTo(W * fx, H * fy); ctx.lineTo(W * (fx + 0.035), hz + 2); ctx.lineTo(W * (fx + 0.012), hz + 2); ctx.closePath(); ctx.fill(); }
      ctx.fillStyle = '#f4f6fa'; pk.forEach(([fx, fy]) => { if (fy > 0.30) return; ctx.beginPath(); ctx.moveTo(W * fx, H * fy); ctx.lineTo(W * (fx + 0.022), H * (fy + 0.028)); ctx.lineTo(W * (fx + 0.008), H * (fy + 0.022)); ctx.lineTo(W * (fx - 0.006), H * (fy + 0.03)); ctx.lineTo(W * (fx - 0.02), H * (fy + 0.026)); ctx.closePath(); ctx.fill(); });
      ctx.fillStyle = 'rgba(230,236,240,0.35)'; ctx.fillRect(0, H * 0.33, W, hz - H * 0.33 + 2); ctx.restore(); }
    // ── red mesas and buttes, nearer: a lit face and a shade face, caprock, gullies ──
    const mesa = (pts, lit, shade) => { poly(pts); const xs = pts.map(p => p[0]), x0 = Math.min(...xs), x1 = Math.max(...xs), yt = Math.min(...pts.map(p => p[1])); const g = ctx.createLinearGradient(x0, 0, x1, 0); g.addColorStop(0, lit); g.addColorStop(0.62, lit); g.addColorStop(0.66, shade); g.addColorStop(1, shade); ctx.fillStyle = g; ctx.fill();
      ctx.save(); ctx.clip(); ctx.strokeStyle = 'rgba(110,40,20,0.25)'; ctx.lineWidth = 0.7; for (let y = yt + 4; y < hz; y += 3 + rnd() * 3) seg([x0, y], [x1, y + (rnd() - 0.5) * 1.5]);
      for (let k = 0; k < 6; k++) { const x = x0 + rnd() * (x1 - x0), l = 4 + rnd() * (hz - yt) * 0.5, sg = ctx.createLinearGradient(0, yt, 0, yt + l); sg.addColorStop(0, 'rgba(80,26,14,0.45)'); sg.addColorStop(1, 'rgba(80,26,14,0)'); ctx.fillStyle = sg; ctx.fillRect(x, yt + 2, 1.2, l); }
      ctx.fillStyle = 'rgba(110,34,16,0.5)'; ctx.fillRect(x0, yt - 1, x1 - x0, 3); ctx.fillStyle = 'rgba(220,230,240,0.22)'; ctx.fillRect(x0, yt - 2, x1 - x0, hz - yt + 4); ctx.restore(); };
    const M = (fx, fy) => [W * fx, H * fy];
