    mesa([M(0.60, HZ + 0.004), M(0.625, 0.375), M(0.64, 0.356), M(0.643, 0.296), M(0.65, 0.29), M(0.70, 0.292), M(0.704, 0.356), M(0.73, 0.38), M(0.76, HZ + 0.004)], '#e8763e', '#a8482a');
    mesa([M(0.706, 0.358), M(0.708, 0.322), M(0.713, 0.317), M(0.718, 0.323), M(0.72, 0.358)], '#e8763e', '#a8482a');
