      { const [ex, ey] = P(sx, h - 0.7, z1), [, eb] = P(sx, 0, z1), g = ctx.createLinearGradient(0, ey, 0, eb); g.addColorStop(0, 'rgba(40,20,30,0)'); g.addColorStop(1, 'rgba(40,20,30,0.3)'); poly([P(sx, 0, z1), P(side * 16, 0, z1), P(side * 16, h - 0.7, z1), P(sx, h - 0.7, z1)], g); }
