    const core = ctx.createRadialGradient(0, 0, 0, 0, 0, r); core.addColorStop(0, 'rgba(110,70,30,0.55)'); core.addColorStop(0.7, 'rgba(130,90,46,0.30)'); core.addColorStop(1, 'rgba(130,90,46,0)'); ctx.fillStyle = core; ctx.beginPath(); ctx.arc(0, 0, r, 0, PI * 2); ctx.fill();
