    ctx.fillStyle = L.hat; ctx.beginPath(); ctx.moveTo(-9.6, 0.2); ctx.quadraticCurveTo(-10.4, -1.6, -8.6, -1.2); ctx.quadraticCurveTo(0, -2.6, 8.6, -1.2); ctx.quadraticCurveTo(10.4, -1.6, 9.6, 0.2); ctx.quadraticCurveTo(0, 2.4, -9.6, 0.2); ctx.closePath(); ctx.fill();
