      ctx.beginPath(); ctx.moveTo(-2.4, -4.2); ctx.lineTo(1.8, -4.2); ctx.lineTo(2.2, -1.6); ctx.quadraticCurveTo(5.6, -1.4, 5.4, 0.6); ctx.lineTo(-0.6, 0.6); ctx.lineTo(-0.9, 1.4); ctx.lineTo(-2.6, 1.4); ctx.closePath(); ctx.fill();
