    ctx.fillStyle = 'rgba(255,255,255,0.35)'; poly(ctx, PX(W, H, [[0.02, 0.38], [0.045, 0.36], [0.03, 0.50], [-0.02, 0.52]])); ctx.fill();
    ctx.fillStyle = 'rgba(170,160,220,0.2)'; poly(ctx, PX(W, H, [[0.18, 0.31], [0.205, 0.265], [0.198, 0.40], [0.175, 0.44]])); ctx.fill();
    // the ridge lines catching light
    ctx.strokeStyle = 'rgba(255,250,252,0.85)'; ctx.lineWidth = 1; [[[0.11, 0.185], [0.118, 0.26], [0.122, 0.33], [0.128, 0.42]], [[0.205, 0.265], [0.212, 0.33], [0.218, 0.42]]].forEach(L => { ctx.beginPath(); PX(W, H, L).forEach(([x, y], k) => k ? ctx.lineTo(x, y) : ctx.moveTo(x, y)); ctx.stroke(); });
