      ctx.translate(px, py + drop); ctx.rotate(lean); ctx.translate(-px, -py); ctx.drawImage(SLABIMG, 0, 0);
      if (lean > 0.002 && lean < 0.02) { ctx.strokeStyle = `rgba(10,30,70,${Math.min(1, lean / 0.012).toFixed(2)})`; ctx.lineWidth = 1.4; ctx.beginPath(); PX(W, H, PIECE.slice(5).concat([PIECE[0]])).forEach(([x, y], k) => k ? ctx.lineTo(x, y) : ctx.moveTo(x, y)); ctx.stroke(); }    // the crack opening along its root
