      ctx.fillStyle = 'rgba(6,2,4,0.55)'; ctx.beginPath(); ctx.moveTo(sx - 11, sb); ctx.lineTo(sx + 11, sb); ctx.lineTo(sx + 16, sb + 10); ctx.lineTo(sx - 8, sb + 10); ctx.closePath(); ctx.fill();
