    seg(ctx, R, 18 + sw * 6, `rgba(255,80,20,${(0.12 + sw * 0.08).toFixed(2)})`); seg(ctx, R, 7, `rgba(255,${104 + sw * 40 | 0},30,${(0.85 + 0.1 * Math.sin(t * 1.3)).toFixed(2)})`); seg(ctx, R, 2.8, 'rgba(255,200,100,0.85)'); seg(ctx, R, 1, 'rgba(255,250,210,0.9)');
