    ctx.save(); ctx.translate(hx + 4, hy + 2); ctx.scale(1.25, 1.25); ctx.rotate(-0.15 - lift * 0.25); ctx.beginPath(); ctx.moveTo(4, -2); ctx.quadraticCurveTo(0, -5, -4, -3); ctx.quadraticCurveTo(-9, -2.4, -10, 0); ctx.lineTo(-4, 1.8); ctx.quadraticCurveTo(2, 3, 4, 1); ctx.closePath(); ctx.fill();   // head with a domed brow and blunt snout
