    ctx.fillStyle = '#2a2622'; ctx.beginPath(); ctx.moveTo(-10.6, -2); ctx.quadraticCurveTo(-14, -1.6, -12.4, 1.4); ctx.lineTo(-10.6, 0.6); ctx.closePath(); ctx.fill();   // big hooked beak
