    ['255,70,70', '255,160,50', '255,240,90', '90,240,120', '80,160,255', '150,90,255'].forEach((c, i) => { ctx.strokeStyle = `rgba(${c},${k.toFixed(2)})`; ctx.lineWidth = 3.4; ctx.beginPath(); ctx.arc(330, 330, 250 - i * 3.3, PI * 1.08, PI * 1.92); ctx.stroke(); });
