  // ════════ MONKEYS — a pair of spider monkeys swinging hand over hand across the canopy ════════
  const ANCH = [-50, 70, 190, 310, 430, 550, 680];
  function monkeyAt(m, lag) { const u = win(m, [MONKEYS[0] + lag, MONKEYS[1] + lag]); if (u < 0) return null; const p = u * (ANCH.length - 1), i = Math.min(ANCH.length - 2, Math.floor(p)), f = p - i; return { i, f, x: lerp(ANCH[i], ANCH[i + 1], f), y: 30 + Math.sin(f * PI) * 14 }; }
