  function drawSignal(ctx, W, H, t) { const m = t % SHOW, u = win(m, [WHISTLE[0] + 0.6, WHISTLE[1] + 1.2]); if (u < 0) return; const k = Math.max(0, Math.sin(u * PI * 6)) * Math.sin(u * PI), [x, y] = consortPos(t), lx = x - 4, ly = y + 27;
    ctx.save(); ctx.globalCompositeOperation = 'lighter'; const g = ctx.createRadialGradient(lx, ly, 0, lx, ly, 22); g.addColorStop(0, `rgba(255,250,220,${(0.9 * k).toFixed(3)})`); g.addColorStop(0.2, `rgba(255,220,150,${(0.4 * k).toFixed(3)})`); g.addColorStop(1, 'rgba(255,200,120,0)'); ctx.fillStyle = g; ctx.fillRect(lx - 22, ly - 22, 44, 44); ctx.restore(); }
