    for (let k = 1; k <= 8; k++) { const uu = u - k * 0.012; if (uu < 0) break; const [x, y] = sixPos(uu); ctx.fillStyle = `rgba(255,236,200,${(0.4 * (1 - k / 9)).toFixed(2)})`; ctx.beginPath(); ctx.arc(x, y, Math.max(0.6, 3.6 - k * 0.25 - uu * 2.2), 0, TAU); ctx.fill(); }
